using System.Globalization;
using System.Text;

namespace TreeSpitter.Grammars;

/// <summary>The error thrown for an invalid <c>grammar.json</c> file.</summary>
public sealed class GrammarFormatException : Exception
{
    /// <summary>Creates an error.</summary>
    public GrammarFormatException(string message) : base(message)
    {
    }
}

/// <summary>
/// Reads the <c>grammar.json</c> files generated by <c>tree-sitter generate</c>, without a JavaScript engine (the source
/// generator reads grammars with it).
/// </summary>
public static class GrammarJsonReader
{
    /// <summary>Reads a <c>grammar.json</c> document.</summary>
    public static Grammar Read(string json)
    {
        if (json is null)
        {
            throw new ArgumentNullException(nameof(json));
        }

        var parser = new JsonParser(json);
        var value = parser.ParseDocument();
        return ToGrammar(value);
    }

    private static Grammar ToGrammar(object? value)
    {
        var grammar = AsObject(value, "grammar");

        var rules = new List<GrammarRule>();
        foreach (var (name, rule) in AsObject(Get(grammar, "rules"), "rules"))
        {
            rules.Add(new GrammarRule(name, ToRule(rule, name)));
        }

        var reserved = new List<ReservedWordSet>();
        if (Get(grammar, "reserved") is List<KeyValuePair<string, object?>> reservedObject)
        {
            foreach (var (name, set) in reservedObject)
            {
                reserved.Add(new ReservedWordSet(name, ToRules(set, "reserved." + name)));
            }
        }

        var extras = Get(grammar, "extras");
        return new Grammar
        {
            Name = ToStringValue(Get(grammar, "name"), "name") ?? throw new GrammarFormatException("The grammar has no name."),
            Inherits = ToStringValue(Get(grammar, "inherits"), "inherits"),
            Word = ToStringValue(Get(grammar, "word"), "word"),
            Rules = rules,
            Extras = extras is null ? [new PatternRule("\\s")] : ToRules(extras, "extras"),
            Conflicts = Items(Get(grammar, "conflicts"), "conflicts").Select(c => ToStrings(c, "conflicts")).ToList(),
            Precedences = Items(Get(grammar, "precedences"), "precedences").Select(p => ToRules(p, "precedences")).ToList(),
            Externals = ToRules(Get(grammar, "externals"), "externals"),
            Inline = ToStrings(Get(grammar, "inline"), "inline"),
            Supertypes = ToStrings(Get(grammar, "supertypes"), "supertypes"),
            Reserved = reserved,
        };
    }

    private static Rule ToRule(object? value, string context)
    {
        var rule = AsObject(value, context);
        var type = ToStringValue(Get(rule, "type"), context) ?? throw new GrammarFormatException($"Invalid rule in '{context}': the 'type' property is missing.");
        return type switch
        {
            "BLANK" => BlankRule.Instance,
            "EOF" => EofRule.Instance,
            "STRING" => new StringRule(Required(rule, "value", context)),
            "PATTERN" => new PatternRule(Required(rule, "value", context), ToStringValue(Get(rule, "flags"), context) ?? string.Empty),
            "SYMBOL" => new SymbolRule(Required(rule, "name", context)),
            "SEQ" => new SeqRule(ToRules(Get(rule, "members"), context)),
            "CHOICE" => new ChoiceRule(ToRules(Get(rule, "members"), context)),
            "REPEAT" => new RepeatRule(ToRule(Get(rule, "content"), context)),
            "REPEAT1" => new Repeat1Rule(ToRule(Get(rule, "content"), context)),
            "PREC" => new PrecRule(PrecedenceKind.Default, ToPrecedence(Get(rule, "value"), context), ToRule(Get(rule, "content"), context)),
            "PREC_LEFT" => new PrecRule(PrecedenceKind.Left, ToPrecedence(Get(rule, "value"), context), ToRule(Get(rule, "content"), context)),
            "PREC_RIGHT" => new PrecRule(PrecedenceKind.Right, ToPrecedence(Get(rule, "value"), context), ToRule(Get(rule, "content"), context)),
            "PREC_DYNAMIC" => new PrecRule(PrecedenceKind.Dynamic, ToPrecedence(Get(rule, "value"), context), ToRule(Get(rule, "content"), context)),
            "TOKEN" => new TokenRule(ToRule(Get(rule, "content"), context)),
            "IMMEDIATE_TOKEN" => new TokenRule(ToRule(Get(rule, "content"), context), Immediate: true),
            "ALIAS" => new AliasRule(ToRule(Get(rule, "content"), context), Required(rule, "value", context), Get(rule, "named") is true),
            "FIELD" => new FieldRule(Required(rule, "name", context), ToRule(Get(rule, "content"), context)),
            "RESERVED" => new ReservedRule(Required(rule, "context_name", context), ToRule(Get(rule, "content"), context)),
            _ => throw new GrammarFormatException($"Unknown rule type '{type}' in '{context}'."),
        };
    }

    private static PrecedenceValue ToPrecedence(object? value, string context) => value switch
    {
        double number => new PrecedenceValue(checked((int)number)),
        string name => new PrecedenceValue(name),
        _ => throw new GrammarFormatException($"Invalid precedence value in '{context}'."),
    };

    private static List<Rule> ToRules(object? value, string context) => Items(value, context).Select(i => ToRule(i, context)).ToList();

    private static List<string> ToStrings(object? value, string context) =>
        Items(value, context).Select(i => ToStringValue(i, context) ?? throw new GrammarFormatException($"Invalid value in '{context}'.")).ToList();

    private static IEnumerable<object?> Items(object? value, string context) => value switch
    {
        null => [],
        List<object?> list => list,
        _ => throw new GrammarFormatException($"Expected an array in '{context}'."),
    };

    private static List<KeyValuePair<string, object?>> AsObject(object? value, string context) =>
        value as List<KeyValuePair<string, object?>> ?? throw new GrammarFormatException($"Invalid value in '{context}': expected an object.");

    private static object? Get(List<KeyValuePair<string, object?>> obj, string name)
    {
        foreach (var (key, value) in obj)
        {
            if (key == name)
            {
                return value;
            }
        }

        return null;
    }

    private static string Required(List<KeyValuePair<string, object?>> rule, string property, string context) =>
        ToStringValue(Get(rule, property), context) ?? throw new GrammarFormatException($"Invalid rule in '{context}': the '{property}' property is missing.");

    private static string? ToStringValue(object? value, string context) => value switch
    {
        null => null,
        string s => s,
        _ => throw new GrammarFormatException($"Invalid value in '{context}': expected a string."),
    };

    /// <summary>A minimal JSON parser: objects are ordered lists of properties, numbers are doubles.</summary>
    private sealed class JsonParser(string text)
    {
        private int _position;

        public object? ParseDocument()
        {
            var value = ParseValue();
            SkipWhiteSpace();
            if (_position < text.Length)
            {
                throw Error("unexpected content after the document");
            }

            return value;
        }

        private object? ParseValue()
        {
            SkipWhiteSpace();
            if (_position >= text.Length)
            {
                throw Error("unexpected end of the document");
            }

            switch (text[_position])
            {
                case '{':
                    return ParseObject();
                case '[':
                    return ParseArray();
                case '"':
                    return ParseString();
                case 't':
                    Expect("true");
                    return true;
                case 'f':
                    Expect("false");
                    return false;
                case 'n':
                    Expect("null");
                    return null;
                default:
                    return ParseNumber();
            }
        }

        private List<KeyValuePair<string, object?>> ParseObject()
        {
            var result = new List<KeyValuePair<string, object?>>();
            _position++;
            SkipWhiteSpace();
            if (Peek() == '}')
            {
                _position++;
                return result;
            }

            while (true)
            {
                SkipWhiteSpace();
                var key = ParseString();
                SkipWhiteSpace();
                if (Peek() != ':')
                {
                    throw Error("expected ':'");
                }

                _position++;
                result.Add(new KeyValuePair<string, object?>(key, ParseValue()));
                SkipWhiteSpace();
                var c = Peek();
                _position++;
                if (c == '}')
                {
                    return result;
                }

                if (c != ',')
                {
                    throw Error("expected ',' or '}'");
                }
            }
        }

        private List<object?> ParseArray()
        {
            var result = new List<object?>();
            _position++;
            SkipWhiteSpace();
            if (Peek() == ']')
            {
                _position++;
                return result;
            }

            while (true)
            {
                result.Add(ParseValue());
                SkipWhiteSpace();
                var c = Peek();
                _position++;
                if (c == ']')
                {
                    return result;
                }

                if (c != ',')
                {
                    throw Error("expected ',' or ']'");
                }
            }
        }

        private string ParseString()
        {
            if (Peek() != '"')
            {
                throw Error("expected a string");
            }

            _position++;
            var builder = new StringBuilder();
            while (true)
            {
                if (_position >= text.Length)
                {
                    throw Error("unterminated string");
                }

                var c = text[_position++];
                if (c == '"')
                {
                    return builder.ToString();
                }

                if (c != '\\')
                {
                    builder.Append(c);
                    continue;
                }

                var escape = _position < text.Length ? text[_position++] : '\0';
                switch (escape)
                {
                    case '"':
                    case '\\':
                    case '/':
                        builder.Append(escape);
                        break;
                    case 'b':
                        builder.Append('\b');
                        break;
                    case 'f':
                        builder.Append('\f');
                        break;
                    case 'n':
                        builder.Append('\n');
                        break;
                    case 'r':
                        builder.Append('\r');
                        break;
                    case 't':
                        builder.Append('\t');
                        break;
                    case 'u':
                        if (_position + 4 > text.Length || !int.TryParse(text.Substring(_position, 4), NumberStyles.AllowHexSpecifier, CultureInfo.InvariantCulture, out var code))
                        {
                            throw Error("invalid \\u escape");
                        }

                        builder.Append((char)code);
                        _position += 4;
                        break;
                    default:
                        throw Error("invalid escape");
                }
            }
        }

        private double ParseNumber()
        {
            var start = _position;
            while (_position < text.Length && (char.IsDigit(text[_position]) || text[_position] is '-' or '+' or '.' or 'e' or 'E'))
            {
                _position++;
            }

            if (start == _position || !double.TryParse(text.Substring(start, _position - start), NumberStyles.Float, CultureInfo.InvariantCulture, out var number))
            {
                throw Error("invalid value");
            }

            return number;
        }

        private void Expect(string literal)
        {
            if (string.CompareOrdinal(text, _position, literal, 0, literal.Length) != 0)
            {
                throw Error("invalid value");
            }

            _position += literal.Length;
        }

        private char Peek() => _position < text.Length ? text[_position] : '\0';

        private void SkipWhiteSpace()
        {
            while (_position < text.Length && text[_position] is ' ' or '\t' or '\r' or '\n')
            {
                _position++;
            }
        }

        private GrammarFormatException Error(string message) => new($"Invalid grammar.json at offset {_position}: {message}.");
    }
}
